DRYF = os.path.basename(DRY[-1]) if DRY else 'repin_dryrun_1.out'
fill = rd('fill_1.out'); now = datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
