CH, CD = 'fa93ff88f47e', '8af6ab821600'   # the prefixes Wednesday's gate42 commission named ("re-read it by `git ls-remote` before you trust it")
launch = '%s/repin_and_launch_%s.sh %s %s' % (D, kit, L, SP)
m = re.search(r'#%s (\d+)->(\d+)' % n, fill)
subj = 'declared %s, lands at %s' % (m.group(1), m.group(2)) if m else '?'
CZ = P['measured'][n]['census']
ntests = len({x for v in CZ['exact'].values() for x in v} | set(CZ['broad']) | set(CZ['email_importers']['services/auth']) | set(CZ['email_importers']['services/originate']))
